import React, { useState, useEffect } from 'react';
import { Elements } from '@stripe/react-stripe-js';
import { loadStripe } from '@stripe/stripe-js';
import PaymentModal from '../components/PaymentModal';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import DiscoveryPage from './DiscoveryPage';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY);

function CustomerDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [services, setServices] = useState([]);
  const [vehicles, setVehicles] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [onlineDrivers, setOnlineDrivers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showBookingModal, setShowBookingModal] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [selectedService, setSelectedService] = useState(null);
  const [pendingBooking, setPendingBooking] = useState(null);
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  const [darkMode, setDarkMode] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(3);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showDiscovery, setShowDiscovery] = useState(false);

  const [bookingData, setBookingData] = useState({
    date: '',
    time: '',
    vehicleId: '',
    isConcierge: false,
    pickupAddress: '',
    notes: ''
  });

  const [profile, setProfile] = useState({
    fullName: `${user?.firstName || ''} ${user?.lastName || ''}`,
    email: user?.email || '',
    phone: user?.phone || '',
    avatar: user?.profilePicture || 'https://ui-avatars.com/api/?background=2563eb&color=fff&name=' + encodeURIComponent(user?.firstName || 'User'),
    preferredLocation: user?.address || '',
    loyaltyPoints: 1250,
    memberSince: new Date(user?.createdAt || Date.now()).toLocaleDateString()
  });

  const [settings, setSettings] = useState({
    emailNotifications: true,
    pushNotifications: true,
    smsNotifications: false,
    darkMode: false,
    language: 'english',
    hideProfile: false,
    offlineMode: false
  });

  const [newVehicle, setNewVehicle] = useState({ make: '', model: '', year: '', licensePlate: '', color: '' });
  const [filters, setFilters] = useState({ category: 'all', search: '', minPrice: '', maxPrice: '' });
  const [selectedDate, setSelectedDate] = useState(new Date());

  const token = localStorage.getItem('token');

  const sampleNotifications = [
    { id: 1, type: 'booking_confirmed', title: 'Booking Confirmed', message: 'Your service has been confirmed', time: '2 hours ago', read: false, icon: '✅' },
    { id: 2, type: 'driver_assigned', title: 'Driver Assigned', message: 'A driver has been assigned', time: '5 hours ago', read: false, icon: '🚗' }
  ];

  useEffect(() => {
    fetchAllData();
    setNotifications(sampleNotifications);
    const interval = setInterval(fetchOnlineDrivers, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      await Promise.all([
        fetchServices(),
        fetchVehicles(),
        fetchBookings(),
        fetchOnlineDrivers()
      ]);
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const fetchServices = async () => {
    try {
      let url = 'http://localhost:5000/api/services?';
      if (filters.category && filters.category !== 'all') url += `category=${filters.category}&`;
      if (filters.search) url += `search=${filters.search}&`;
      if (filters.minPrice) url += `minPrice=${filters.minPrice}&`;
      if (filters.maxPrice) url += `maxPrice=${filters.maxPrice}&`;

      const res = await fetch(url);
      const data = await res.json();
      if (data.success) setServices(data.services);
    } catch (error) {
      console.error('Error fetching services:', error);
    }
  };

  const fetchVehicles = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/services/customer/vehicles', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) setVehicles(data.vehicles);
    } catch (error) {
      console.error('Error fetching vehicles:', error);
    }
  };

  const fetchBookings = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/services/customer/bookings', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) setBookings(data.bookings);
    } catch (error) {
      console.error('Error fetching bookings:', error);
    }
  };

  const fetchOnlineDrivers = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/driver/online');
      const data = await res.json();
      if (data.success) setOnlineDrivers(data.drivers);
    } catch (error) {
      console.error('Error fetching drivers:', error);
    }
  };

  // CREATE BOOKING WITH PAYMENT
  const createBooking = async () => {
    if (!bookingData.date) {
      toast.error('Please select a date');
      return;
    }
    if (!bookingData.time) {
      toast.error('Please select a time');
      return;
    }
    if (vehicles.length === 0 && !bookingData.vehicleId) {
      toast.error('Please add a vehicle first');
      setShowVehicleModal(true);
      return;
    }

    const vehicleId = bookingData.vehicleId || (vehicles[0]?._id);
    if (!vehicleId) {
      toast.error('Please select a vehicle');
      return;
    }

    try {
      const payload = {
        serviceId: selectedService._id,
        vehicleId: vehicleId,
        bookingDate: bookingData.date,
        bookingTime: bookingData.time,
        isConcierge: bookingData.isConcierge,
        pickupAddress: bookingData.pickupAddress,
        notes: bookingData.notes
      };

      console.log('Creating booking with payload:', payload);

      const res = await fetch('http://localhost:5000/api/services/customer/bookings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(payload)
      });

      const data = await res.json();
      console.log('Booking response:', data);

      if (data.success) {
        setPendingBooking(data.booking);
        setShowBookingModal(false);
        setShowPaymentModal(true); // Show payment modal after booking
      } else {
        toast.error(data.error || 'Failed to create booking');
      }
    } catch (error) {
      console.error('Error creating booking:', error);
      toast.error('Failed to create booking. Please try again.');
    }
  };

  const handlePaymentSuccess = () => {
    setShowPaymentModal(false);
    setPendingBooking(null);
    setSelectedService(null);
    setBookingData({ date: '', time: '', vehicleId: '', isConcierge: false, pickupAddress: '', notes: '' });
    toast.success('Booking confirmed and payment successful!');
    fetchBookings();
  };

  const handlePaymentCancel = () => {
    setShowPaymentModal(false);
    setPendingBooking(null);
    toast.info('Booking saved. Complete payment later in My Bookings.');
    fetchBookings();
  };

  const addVehicle = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/services/customer/vehicles', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(newVehicle)
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Vehicle added successfully!');
        setShowVehicleModal(false);
        setNewVehicle({ make: '', model: '', year: '', licensePlate: '', color: '' });
        fetchVehicles();
      }
    } catch (error) {
      toast.error('Failed to add vehicle');
    }
  };

  const updateProfile = async (e) => {
    e.preventDefault();
    toast.success('Profile updated successfully!');
    setShowProfileModal(false);
  };

  const updateSettings = async (e) => {
    e.preventDefault();
    setDarkMode(settings.darkMode);
    toast.success('Settings saved!');
    setShowSettingsModal(false);
  };

  const markNotificationRead = (id) => {
    setNotifications(notifications.map(n => n.id === id ? { ...n, read: true } : n));
    setUnreadCount(notifications.filter(n => !n.read && n.id !== id).length);
  };

  const markAllRead = () => {
    setNotifications(notifications.map(n => ({ ...n, read: true })));
    setUnreadCount(0);
  };

  const getStatusBadge = (status) => {
    const colors = { pending: '#f59e0b', confirmed: '#10b981', 'in-progress': '#3b82f6', completed: '#8b5cf6', cancelled: '#ef4444' };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px', display: 'inline-block' };
  };

  const totalSpent = bookings.filter(b => b.status === 'completed').reduce((sum, b) => sum + (b.totalAmount || 0), 0);
  const upcomingBookings = bookings.filter(b => b.status !== 'completed' && b.status !== 'cancelled');
  const completedBookings = bookings.filter(b => b.status === 'completed');

  if (showDiscovery) {
    return <DiscoveryPage user={user} onBack={() => setShowDiscovery(false)} />;
  }

  return (
    <div style={{ ...styles.dashboard, backgroundColor: darkMode ? '#1a1a2e' : '#f3f4f6' }}>
      <ToastContainer position="top-right" />

      {/* Header */}
      <div style={{ ...styles.header, backgroundColor: darkMode ? '#16213e' : '#1f2937' }}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>🚗💨</span>
          <h1 style={styles.logoText}>Car Care Connect</h1>
        </div>
        <div style={styles.headerRight}>
          <div style={styles.notificationIcon} onClick={() => setShowNotifications(!showNotifications)}>🔔{unreadCount > 0 && <span style={styles.notificationBadge}>{unreadCount}</span>}</div>
          <button style={styles.themeToggle} onClick={() => { setDarkMode(!darkMode); setSettings({...settings, darkMode: !darkMode}); }}>{darkMode ? '☀️' : '🌙'}</button>
          <button style={styles.discoveryBtn} onClick={() => setShowDiscovery(true)}>🔍 Discover</button>
          <div style={styles.userInfo}>
            <img src={profile.avatar} alt="avatar" style={styles.avatar} />
            <span>{user?.firstName} {user?.lastName}</span>
            <button onClick={onLogout} style={styles.logoutButton}>Logout</button>
          </div>
        </div>
      </div>

      {/* Rest of your existing JSX - Stats Cards, Tabs, etc. */}
      {/* I'm keeping the existing dashboard code, just adding the payment modal at the end */}

      {/* Payment Modal */}
      {showPaymentModal && pendingBooking && (
        <Elements stripe={stripePromise}>
          <PaymentModal 
            booking={pendingBooking}
            amount={pendingBooking.totalAmount}
            onSuccess={handlePaymentSuccess}
            onCancel={handlePaymentCancel}
          />
        </Elements>
      )}

      {/* Existing modals (Booking, Vehicle, Profile, Settings) */}
      {/* ... keep your existing modal code ... */}
    </div>
  );
}

const styles = {
  dashboard: { minHeight: '100vh', transition: 'background-color 0.3s' },
  header: { padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap' },
  logoSection: { display: 'flex', alignItems: 'center', gap: '10px' },
  logoIcon: { fontSize: '28px' },
  logoText: { fontSize: '1.5rem', fontWeight: 'bold', color: 'white' },
  headerRight: { display: 'flex', alignItems: 'center', gap: '15px' },
  notificationIcon: { position: 'relative', cursor: 'pointer', fontSize: '24px' },
  notificationBadge: { position: 'absolute', top: '-5px', right: '-10px', backgroundColor: '#ef4444', color: 'white', fontSize: '10px', padding: '2px 6px', borderRadius: '10px' },
  themeToggle: { background: 'none', border: 'none', fontSize: '20px', cursor: 'pointer', padding: '5px 10px', borderRadius: '20px', backgroundColor: 'rgba(255,255,255,0.2)' },
  discoveryBtn: { background: 'none', border: '1px solid white', color: 'white', padding: '5px 12px', borderRadius: '20px', cursor: 'pointer', fontSize: '14px' },
  avatar: { width: '35px', height: '35px', borderRadius: '50%', objectFit: 'cover' },
  userInfo: { display: 'flex', gap: '15px', alignItems: 'center', color: 'white' },
  logoutButton: { backgroundColor: 'transparent', border: '1px solid white', color: 'white', padding: '6px 15px', borderRadius: '6px', cursor: 'pointer' },
};

export default CustomerDashboard;
